metrics.workdir_dsl:
workspace "Bank Portal" "An online banking platform where customers manage their accounts, move money, and track their activity." {

    model {

        customer = person "Bank Customer" "A customer of the bank who manages accounts, moves money, and tracks activity."

        bankPortal = softwareSystem "Bank Portal" "The online banking platform owned and operated by the bank, where customers manage accounts, move money, and track activity." {

            webPortal = container "Web Portal" "The web portal where customers log in and manage their accounts." "Web application" "Web"
            mobileAppBackend = container "Mobile App Backend" "The backend that serves the bank's mobile app." "REST API"
            accountService = container "Account Service" "Holds the customer account records." "Microservice"
            transactionService = container "Transaction Service" "Processes deposits, withdrawals, and transfers." "Microservice"
            paymentService = container "Payment Service" "Executes card payments and bank transfers." "Microservice"
            cardService = container "Card Service" "Manages debit and credit cards." "Microservice"
            fraudDetectionService = container "Fraud Detection Service" "Scores transactions for fraud." "Microservice"
            notificationService = container "Notification Service" "Sends email and SMS alerts." "Microservice"
            onboardingService = container "Onboarding Service" "Verifies new customers." "Microservice"
            statementsService = container "Statements Service" "Generates monthly statements." "Microservice"
            directDebitService = container "Direct Debit Service" "Processes standing orders and direct debits." "Microservice"
            exchangeRatesService = container "Exchange Rates Service" "Provides currency conversion rates." "Microservice"
            batchScheduler = container "Batch Scheduler" "Runs the nightly interest calculation and reconciliation." "Batch job"
            eventQueue = container "Event Queue" "Carries internal events between the application parts." "Message queue" "Queue"
            ledgerDb = container "Ledger Database" "Stores every account movement." "SQL database" "Database"
            customerDb = container "Customer Database" "Stores account and profile records." "SQL database" "Database"
            auditDb = container "Audit Database" "Stores the compliance audit trail." "SQL database" "Database"
            cache = container "Cache" "Stores sessions and frequently read account data." "In-memory cache"
            documentStore = container "Document Store" "Holds the generated statement PDFs." "Object storage"
        }

        cardPaymentNetwork = softwareSystem "Card Payment Network" "The card payment network operated by a different organization that routes card authorisations." "External"
        creditReferenceAgency = softwareSystem "Credit Reference Agency" "The credit reference agency operated by a different organization that performs credit checks." "External"

        customer -> webPortal "Logs in and manages accounts" "HTTPS/JSON"
        customer -> mobileAppBackend "Uses the mobile app" "HTTPS/JSON"

        webPortal -> accountService "Manages accounts through" "HTTPS/JSON"
        webPortal -> transactionService "Initiates transactions through" "HTTPS/JSON"
        webPortal -> paymentService "Initiates payments through" "HTTPS/JSON"
        webPortal -> cardService "Manages cards through" "HTTPS/JSON"
        webPortal -> statementsService "Views statements through" "HTTPS/JSON"
        webPortal -> directDebitService "Manages direct debits through" "HTTPS/JSON"

        mobileAppBackend -> accountService "Manages accounts through" "HTTPS/JSON"
        mobileAppBackend -> transactionService "Initiates transactions through" "HTTPS/JSON"
        mobileAppBackend -> paymentService "Initiates payments through" "HTTPS/JSON"
        mobileAppBackend -> cardService "Manages cards through" "HTTPS/JSON"
        mobileAppBackend -> statementsService "Views statements through" "HTTPS/JSON"
        mobileAppBackend -> directDebitService "Manages direct debits through" "HTTPS/JSON"

        transactionService -> ledgerDb "Records account movements in" "SQL"
        transactionService -> fraudDetectionService "Scores transactions with" "gRPC"
        transactionService -> eventQueue "Publishes events to" "Kafka"

        notificationService -> eventQueue "Consumes events from" "Kafka"

        statementsService -> ledgerDb "Reads account movements from" "SQL"
        statementsService -> documentStore "Writes statement PDFs to" "S3"

        batchScheduler -> ledgerDb "Reads and writes account movements" "SQL"
        batchScheduler -> customerDb "Reads and writes customer records" "SQL"

        paymentService -> cardService "Requests card details from" "gRPC"
        paymentService -> exchangeRatesService "Requests exchange rates from" "gRPC"

        onboardingService -> customerDb "Reads customer records from" "SQL"

        paymentService -> cardPaymentNetwork "Routes card authorisations through" "HTTPS/JSON"
        onboardingService -> creditReferenceAgency "Performs credit checks through" "HTTPS/JSON"
    }

    views {

        systemContext bankPortal "SystemContext" "The Bank Portal system, its customer, and the external systems it interacts with." {
            include *
            autoLayout
            title "System Context for Bank Portal"
        }

        container bankPortal "Containers" "The containers that make up the Bank Portal system and how they interact." {
            include *
            autoLayout
            title "Containers for Bank Portal"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            element "Web" {
                shape WebBrowser
            }
            element "Queue" {
                shape Pipe
            }
            relationship "Relationship" {
                routing Orthogonal
            }
        }
    }

    configuration {
        scope softwaresystem
    }
}
